package main

import (
	"fmt"
)

const m = 1000000007

func power(a, b int64) int64 {
	var ans int64 = 1
	if b == 0 {
		return 1
	}
	for b > 0 {
		if b%2 != 0 {
			ans = (ans * a) % m
		}
		a = (a * a) % m
		b = b / 2
	}
	return ans
}

func main() {
	var n int64
	fmt.Scan(&n)
	var i int64 = 0
	var index int64 = 0
	for n > 0 {
		rem := n % 10
		if rem == 4 {
			index = (index + power(2, i)) % m
		} else {
			index = (index + power(2, i+1)) % m
		}
		n = n / 10
		i++
	}
	fmt.Println(index)
}
